// ── GDS-15 — mood ────────────────────────────────────────────────────────────
// Yesavage & Sheikh. Public domain. One point per answer in the direction of
// depression; 5 or more: talk with them carefully and ask the GP to assess.

const GDS: [string, 'yes' | 'no'][] = [
  ['Are you basically satisfied with your life?', 'no'],
  ['Have you dropped many of your activities and interests?', 'yes'],
  ['Do you feel that your life is empty?', 'yes'],
  ['Do you often get bored?', 'yes'],
  ['Are you in good spirits most of the time?', 'no'],
  ['Are you afraid that something bad is going to happen to you?', 'yes'],
  ['Do you feel happy most of the time?', 'no'],
  ['Do you often feel helpless?', 'yes'],
  ['Do you prefer to stay in, rather than going out and doing new things?', 'yes'],
  ['Do you feel you have more problems with memory than most?', 'yes'],
  ['Do you think it is wonderful to be alive now?', 'no'],
  ['Do you feel pretty worthless the way you are now?', 'yes'],
  ['Do you feel full of energy?', 'no'],
  ['Do you feel that your situation is hopeless?', 'yes'],
  ['Do you think that most people are better off than you are?', 'yes'],
];

const mood: Tool = {
  key: 'mood_gds15', name: 'Mood — Geriatric Depression Scale (GDS-15)', shortName: 'Mood (GDS-15)', version: 'gds15/cv89',
  purpose: 'Whether low mood or depression might be present, for people who can answer simple yes/no questions about how they feel.',
  who: 'A nurse or senior carer they trust, in private and unhurried. On admission and every 3 months, or sooner if their mood seems to change. Not suitable for people with moderate or severe dementia — see the note at the start.',
  domain: 'cognition_mental_health', scored: true, group: 'wellbeing',
  sources: [
    { label: 'Geriatric Depression Scale (public domain) — Yesavage, Stanford', url: 'https://web.stanford.edu/~yesavage/GDS.html' },
    { label: 'NICE NG222 Depression in adults', url: 'https://www.nice.org.uk/guidance/ng222' },
  ],
  sections: [
    { key: 'can', title: 'Before you start', intro: 'Ask about the past week. Read each question as written; they answer yes or no.', questions: [
      { key: 'able', label: 'Can they understand and answer simple questions about how they feel?', type: 'choice', options: [
        { value: 'yes', label: 'Yes' },
        { value: 'no', label: 'No — use observation instead (ask the GP or mental health team for an observational assessment)' },
      ] },
    ] },
    { key: 'questions', title: 'The 15 questions', questions: GDS.map(([text], i) => ({
      key: `g${i + 1}`, label: `${i + 1}. ${text}`, type: 'choice' as const, showIf: (a: Answers) => a.able === 'yes',
      options: [{ value: 'yes', label: 'Yes' }, { value: 'no', label: 'No' }, { value: 'na', label: 'Did not answer' }],
    })) },
  ],
  evaluate(a) {
    const t = mood;
    const r = base(t, a, t.domain);
    if (a.able === 'no') {
      r.level = 'not_scored'; r.storedScore = 0;
      r.headline = 'Cannot answer the questions — observation needed';
      r.actions.push('Ask the GP or community mental health team for an observational assessment of mood (tools designed for people with dementia).');
      r.actions.push('Record what you see over the next week: interest in usual things, appetite, sleep, tearfulness, withdrawal, irritability.');
      r.reviewDays = 28; r.reviewNote = 'And sooner if their mood or behaviour changes.';
      r.plan.need = 'Mood cannot be screened by questions; an observational assessment is needed.';
      r.plan.outcome = 'Low mood is noticed and treated.';
      r.plan.interventions = r.actions.slice();
      return r;
    }
    let score = 0, answered = 0, skipped = 0;
    GDS.forEach(([, dep], i) => {
      const v = str(a[`g${i + 1}`]);
      if (v === 'na') { skipped++; return; }
      if (v === 'yes' || v === 'no') { answered++; if (v === dep) score++; }
    });
    if (skipped > 5) r.errors.push('More than 5 questions were not answered, so the score is not reliable. Use observation instead (answer "No" to the first question).');
    // Yesavage: prorate for a few missed items, rounding up (safer for a screen).
    const total = answered > 0 && skipped > 0 ? Math.ceil((score / answered) * 15) : score;
    r.score = total; r.storedScore = total; r.maxScore = 15;
    if (skipped > 0) r.reasons.push(`${skipped} not answered — score prorated from ${score}/${answered}, rounded up`);
    GDS.forEach(([text, dep], i) => { if (str(a[`g${i + 1}`]) === dep) r.reasons.push(`${text.replace(/\?$/, '')}: ${dep}`); });
    r.level = total >= 10 ? 'high' : total >= 5 ? 'medium' : 'low';
    r.headline = total >= 10 ? `Suggests moderate to severe depression (GDS ${total})` : total >= 5 ? `Suggests possible depression (GDS ${total})` : `Normal range (GDS ${total})`;
    if (total >= 5) {
      r.actions.push('This is a screen, not a diagnosis. Ask the GP to assess their mood.');
      r.actions.push('Spend time talking with them about how they feel and what would help; involve people who matter to them.');
      r.actions.push('Plan meaningful activity and social contact they enjoy, and time outdoors.');
      r.actions.push('Check for physical causes: pain, poor sleep, hearing or sight problems, medicines, thyroid, infection.');
      r.actions.push('If they talk about wanting to die or harming themselves, complete the emotional safety assessment today.');
    } else {
      r.actions.push('No sign of depression on the screen. Repeat in 3 months, or sooner if their mood seems to change.');
    }
    const hopeless = str(a.g14) === 'yes' || str(a.g12) === 'yes';
    if (hopeless) r.warnings.push('They said they feel hopeless or worthless. Ask gently whether they have thoughts of not wanting to live, and complete the emotional safety assessment if so.');
    r.reviewDays = total >= 5 ? 28 : 90;
    r.reviewNote = 'And sooner if their mood, appetite, sleep or interest in things changes.';
    r.plan.riskLevel = r.level === 'high' ? 'high' : r.level === 'medium' ? 'medium' : 'low';
    r.plan.need = `Mood: ${r.headline}.`;
    r.plan.outcome = 'Feels as well in their mood as possible, with things to look forward to each day.';
    r.plan.interventions = r.actions.slice();
    return r;
  },
};

